-- Tags: no-fasttest
-- no-fasttest: requires datasketches library

-- Importing sketches built upstream with a non-default precision must keep that precision instead
-- of degrading them to the defaults (`k = 128` for Quantiles, `k = 100` for t-digest).
-- The fixtures were produced by Apache DataSketches C++: a Quantiles sketch with `k = 1024`
-- holding the 300 values `0..299` (exact mode), and a t-digest with `k = 200` holding `0..249`.

SELECT 'quantiles';
WITH '' AS x
SELECT
    base64Encode(mergeSerializedQuantiles(1)(x)) = x,
    reinterpretAsUInt16(substring(mergeSerializedQuantiles(1)(x), 5, 2)),
    percentileFromQuantiles(mergeSerializedQuantiles(1)(x), 0.5);

-- Through partial states shipped between servers.
SELECT reinterpretAsUInt16(substring(m, 5, 2)), percentileFromQuantiles(m, 0.5)
FROM (SELECT mergeSerializedQuantiles(1)(x) AS m FROM remote('127.0.0.{1,2}', view(SELECT '' AS x)));

SELECT 'tdigest';
WITH '' AS x
SELECT
    length(mergeSerializedTDigest(1)(x)) = length(base64Decode(x)),
    reinterpretAsUInt16(substring(mergeSerializedTDigest(1)(x), 4, 2));

SELECT reinterpretAsUInt16(substring(m, 4, 2))
FROM (SELECT mergeSerializedTDigest(1)(x) AS m FROM remote('127.0.0.{1,2}', view(SELECT '' AS x)));
